<?php
require 'config.php';require_login();$page_title='Positions';$rows=$pdo->query('SELECT p.position_id,p.position_title,COUNT(e.employee_id) headcount FROM positions p LEFT JOIN employees e ON e.position_id=p.position_id GROUP BY p.position_id,p.position_title ORDER BY p.position_title')->fetchAll();include 'includes/header.php';?>
<section class="hero"><div><p class="eyebrow">ROLES & RESPONSIBILITIES</p><h1>Positions</h1><p class="muted">Explore job titles and how many employees hold each position.</p></div><button class="btn outline print-trigger" onclick="window.print()">Print directory</button></section><section class="panel"><div class="panel-head"><h2>Position directory</h2><span class="muted"><?=count($rows)?> position(s)</span></div><div class="table-wrap"><table><thead><tr><th>Position title</th><th>Employees</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?=e($r['position_title'])?></b></td><td><?=number_format($r['headcount'])?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="2" class="empty">No positions found.</td></tr><?php endif; ?></tbody></table></div><p class="muted" style="font-size:12px">Position creation and editing are not included because the existing database setup does not provide a dedicated position-management screen.</p></section><?php include 'includes/footer.php'; ?>